O que você recebe
Após o wallet submeter a VP, GET /v1/verify/vp-result/{transactionId} retorna:
{
  "vpResultStatus": "SUCCESS",
  "vcResults": [
    {
      "vc": { "credentialSubject": { "isOver18": true } },
      "vcStatus": "SUCCESS"
    }
  ]
}
O campo relevante para a decisão é vcResults[0].vc.credentialSubject.isOver18.

Passo 1 — Criar o serviço de verificação
// src/services/verifyService.ts
const BASE_URL = '/v1/verify';
const CLIENT_ID = 'did:web:localhost:v1:verify';

const presentationDefinition = {
  id: 'eca-age-check',
  input_descriptors: [
    {
      id: 'ECACredential',
      name: 'Comprovante de Maioridade',
      purpose: 'Verificar que o usuário é maior de 18 anos',
      format: { ldp_vc: { proof_type: ['Ed25519Signature2020'] } },
      constraints: {
        fields: [
          {
            path: ['$.type'],
            filter: { type: 'string', pattern: 'ECACredential' },
          },
        ],
      },
    },
  ],
};

export async function createVPRequest() {
  const response = await fetch(`${BASE_URL}/vp-request`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ clientId: CLIENT_ID, presentationDefinition }),
  });

  if (!response.ok) throw new Error(`Failed to create VP request: ${response.status}`);

  const data = await response.json();
  const params = new URLSearchParams();
  params.set('client_id', CLIENT_ID);
  params.set('request_uri', data.requestUri);

  return {
    transactionId: data.transactionId,
    requestId: data.requestId,
    deepLinkUrl: `openid4vp://authorize?${params.toString()}`,
  };
}

export async function pollVPStatus(requestId: string): Promise&lt;'ACTIVE' | 'VP_SUBMITTED' | 'EXPIRED'&gt; {
  const response = await fetch(`${BASE_URL}/vp-request/${requestId}/status`);
  if (!response.ok) throw new Error(`Failed to fetch VP status: ${response.status}`);
  const data = await response.json();
  return data.status;
}

export async function getVPResult(transactionId: string) {
  const response = await fetch(`${BASE_URL}/vp-result/${transactionId}`);
  if (!response.ok) throw new Error(`Failed to get VP result: ${response.status}`);

  const data = await response.json();
  if (data.vpResultStatus !== 'SUCCESS' || !data.vcResults?.length) {
    throw new Error(`VP result unavailable: status=${data.vpResultStatus}`);
  }

  const vcRaw = data.vcResults[0].vc;
  const vc = typeof vcRaw === 'string' ? JSON.parse(vcRaw) : vcRaw;
  const subject = vc?.credential?.credentialSubject ?? vc?.credentialSubject ?? vc;

  return { isOver18: subject?.isOver18 === true };
}

export async function pollAndFetchResult(
  requestId: string,
  transactionId: string,
  maxAttempts = 150,
  intervalMs = 2000
): Promise&lt;{ isOver18: boolean } | null&gt; {
  for (let i = 0; i &lt; maxAttempts; i++) {
    const status = await pollVPStatus(requestId);

    if (status === 'VP_SUBMITTED') return getVPResult(transactionId);
    if (status === 'EXPIRED') return null;

    await new Promise((resolve) =&gt; setTimeout(resolve, intervalMs));
  }
  return null;
}

Passo 2 — Criar o hook de verificação
// src/hooks/useAgeVerification.ts
import { useState, useCallback } from 'react';
import { createVPRequest, pollAndFetchResult } from '../services/verifyService';

export function useAgeVerification() {
  const [waiting, setWaiting] = useState(false);
  const [deepLinkUrl, setDeepLinkUrl] = useState&lt;string | null&gt;(null);

  const verify = useCallback(async () =&gt; {
    setWaiting(true);
    setDeepLinkUrl(null);
    try {
      const { requestId, transactionId, deepLinkUrl } = await createVPRequest();
      setDeepLinkUrl(deepLinkUrl);

      const result = await pollAndFetchResult(requestId, transactionId);
      setWaiting(false);
      return result;
    } catch (error) {
      setWaiting(false);
      throw error;
    }
  }, []);

  return { verify, waiting, deepLinkUrl };
}

Passo 3 — Componente de verificação
// src/components/VerificaIdade.tsx
import { useState } from 'react';
import QRCode from 'qrcode.react';
import { useAgeVerification } from '../hooks/useAgeVerification';

export function VerificaIdade() {
  const { verify, waiting, deepLinkUrl } = useAgeVerification();
  const [resultado, setResultado] = useState&lt;{ sucesso: boolean; mensagem: string } | null&gt;(null);

  const handleVerify = async () =&gt; {
    setResultado(null);
    try {
      const result = await verify();
      if (!result) {
        setResultado({ sucesso: false, mensagem: 'Verificação expirada. Tente novamente.' });
        return;
      }
      setResultado(
        result.isOver18
          ? { sucesso: true, mensagem: 'Maior de 18 anos confirmado.' }
          : { sucesso: false, mensagem: 'Usuário menor de 18 anos.' }
      );
    } catch (error) {
      setResultado({
        sucesso: false,
        mensagem: error instanceof Error ? error.message : 'Erro ao verificar idade',
      });
    }
  };

  return (
    &lt;div&gt;
      &lt;h2&gt;Verificação de Idade&lt;/h2&gt;

      {!waiting && !resultado && (
        &lt;button onClick={handleVerify}&gt;Gerar QR Code&lt;/button&gt;
      )}

      {waiting && deepLinkUrl && (
        &lt;div&gt;
          &lt;QRCode value={deepLinkUrl} size={256} /&gt;
          &lt;p&gt;Escaneie com sua carteira digital (INJI Wallet)&lt;/p&gt;
          &lt;p&gt;Aguardando resposta...&lt;/p&gt;
        &lt;/div&gt;
      )}

      {resultado && (
        &lt;div&gt;
          &lt;p&gt;{resultado.mensagem}&lt;/p&gt;
          &lt;button onClick={() =&gt; setResultado(null)}&gt;Voltar&lt;/button&gt;
        &lt;/div&gt;
      )}
    &lt;/div&gt;
  );
}

